import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"旅","description":"焦氏易林注 - 旅","frontmatter":{"title":"旅","description":"焦氏易林注 - 旅"},"headers":[],"relativePath":"zh/classics/jiaoyilin/056.md","filePath":"zh/classics/jiaoyilin/056.md"}'),l={name:"zh/classics/jiaoyilin/056.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="旅" tabindex="-1">旅 <a class="header-anchor" href="#旅" aria-label="Permalink to “旅”">​</a></h1><h3 id="旅-1" tabindex="-1">旅 <a class="header-anchor" href="#旅-1" aria-label="Permalink to “旅”">​</a></h3><h3 id="旅之乾" tabindex="-1">旅之乾 <a class="header-anchor" href="#旅之乾" aria-label="Permalink to “旅之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>寄生無根，如過浮雲。立本不固，斯須落去，更為枯樹。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《蠱》。此用旅象。以艮為寄生，象形，艮下陰，故無根。坎為雲，互巽為枯。</p><h3 id="旅之坤" tabindex="-1">旅之坤 <a class="header-anchor" href="#旅之坤" aria-label="Permalink to “旅之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>人無足法，緩除牛出。雄走羊驚，陽不制陰，男失其家。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>前四句從《既濟》之《屯》，下二句從《觀》之《臨》，各本原作人無定法，緩降牛出。蛇雄走趨，陽不制陰，宜其家困，非。解詳《觀》之《臨》。</p><h3 id="旅之屯" tabindex="-1">旅之屯 <a class="header-anchor" href="#旅之屯" aria-label="Permalink to “旅之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>眾鳥所翔，中有大怪。九身無頭，魂驚魄去，不可以居。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《漸》之《蒙》。翔，宋元本作聚，依汲古。</p><h3 id="旅之蒙" tabindex="-1">旅之蒙 <a class="header-anchor" href="#旅之蒙" aria-label="Permalink to “旅之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>封豕溝瀆，灌潰國邑。火宿口中，民多病疾。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>《史記天官書》奎曰封豕，為溝瀆。正義曰：奎一名天豕，亦曰豕封，主溝瀆，故曰灌潰國邑。坎為豕、為溝瀆，坤為國邑。火，熒惑也。箕為口舌，火宿口中，言熒惑守箕也。艮為火，震為口，艮止，故曰火宿口中。坤為民、坎為疾病。又案：艮為星，故林辭多即星言。</p><h3 id="旅之需" tabindex="-1">旅之需 <a class="header-anchor" href="#旅之需" aria-label="Permalink to “旅之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>奮翅鼓翼，翱翔外國。逍遙徙倚，來歸溫室。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>詳《損》之《觀》。</p><h3 id="旅之訟" tabindex="-1">旅之訟 <a class="header-anchor" href="#旅之訟" aria-label="Permalink to “旅之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>秋蠶不成，冬種不生。殷王逆理，棄其寵榮。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>巽為蠶，旅互兌為秋，兌毀，故不成。坎為冬、為種，震為生，震伏，故不生。震為王、為子，故曰殷王。殷，子姓也。伏坤為理、為逆，震為榮，震伏，故曰棄。○榮，汲古作名，依宋元本。</p><h3 id="旅之師" tabindex="-1">旅之師 <a class="header-anchor" href="#旅之師" aria-label="Permalink to “旅之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>衛侯東游，惑於少姬。忘我考妣，久迷不來。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《升》。忘，汲古作亡，依宋元本。此林屢見而事不見於左傳，疑邶風日居月諸之詩，齊詩家說如此。</p><h3 id="旅之比" tabindex="-1">旅之比 <a class="header-anchor" href="#旅之比" aria-label="Permalink to “旅之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>烏合卒會，與惡相得。鴟鴞相酬，為心所賊。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為烏、為鴟鴞，坤坎皆為聚，故曰會合。坤為惡，坎為心、為賊。○首句元本作鳥合卒會，汲古作鳥會雀合，茲依宋本。</p><h3 id="旅之小畜" tabindex="-1">旅之小畜 <a class="header-anchor" href="#旅之小畜" aria-label="Permalink to “旅之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>眵雞無距，與鵲格鬬。翅折目盲，為鳩所傷。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>巽為雞，兌半離，故曰眵。《說文》目眥傷也。震伏，故曰無距。伏震為鵲、為鬬，為翅，坎為折，故曰翅折。離為目，兌半離，《易》曰眇，故此曰目盲。離為鳩，兌毀故傷。○鵲，汲古作雀，依宋元本。眵，各本皆作鳴，鳩作仇，今依《乾》之《遯》校。</p><h3 id="旅之履" tabindex="-1">旅之履 <a class="header-anchor" href="#旅之履" aria-label="Permalink to “旅之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>木內生蠧，上下相賊，禍亂我國。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>巽為木、為蠧、為賊，天上兌下，正反巽，故上下相賊。離為亂，伏坤為國。</p><h3 id="旅之泰" tabindex="-1">旅之泰 <a class="header-anchor" href="#旅之泰" aria-label="Permalink to “旅之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>延陵適魯，觀樂太史。車轔白顛，知秦興起。卒兼其國，一統為主。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《大畜》之《離》。其為六之形訛字，各本六往往訛其。</p><h3 id="旅之否" tabindex="-1">旅之否 <a class="header-anchor" href="#旅之否" aria-label="Permalink to “旅之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>輔相之好，無有休息。時行雲集，所在遇福。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>艮為時，坤為雲、為集，乾為福。</p><h3 id="旅之同人" tabindex="-1">旅之同人 <a class="header-anchor" href="#旅之同人" aria-label="Permalink to “旅之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>床傾簀折，屋漏垣缺，季姬不愜。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>巽為床簀，巽隕，故傾折。巽為垣墉，伏坎為室、為屋，巽下缺，故曰漏。伏震為姬，易林本大過，每以巽為少，故曰季姬。</p><h3 id="旅之大有" tabindex="-1">旅之大有 <a class="header-anchor" href="#旅之大有" aria-label="Permalink to “旅之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>東入海口，循流北走。一高一下，五邑無主。七日六夜，死於水浦。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>詳《睽》之《蹇》。</p><h3 id="旅之謙" tabindex="-1">旅之謙 <a class="header-anchor" href="#旅之謙" aria-label="Permalink to “旅之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>群虎入邑，求索肉食。大人守御，君不失國。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>正反艮，故曰群虎。伏巽為入，坤為邑，艮為求，坎為肉，故曰求索肉食。伏乾為大人。艮為守御、為國，震為君，故曰君不失國。○虎，宋元本訛需，依汲古。不失，汲古作失其，依宋元本。</p><h3 id="旅之豫" tabindex="-1">旅之豫 <a class="header-anchor" href="#旅之豫" aria-label="Permalink to “旅之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>四亂不安，東西為患。退身止足，無出邦域。乃得完全，賴其生福。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《睽》。止，汲古作山，依宋元本。</p><h3 id="旅之隨" tabindex="-1">旅之隨 <a class="header-anchor" href="#旅之隨" aria-label="Permalink to “旅之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>叔肸抱冤，祁子自邑。乘遽解患，羊舌以免，賴其生全。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《蹇》之《乾》。</p><h3 id="旅之蠱" tabindex="-1">旅之蠱 <a class="header-anchor" href="#旅之蠱" aria-label="Permalink to “旅之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>延頸望酒，不入我口。深目自苦，利得無有。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《益》。</p><h3 id="旅之臨" tabindex="-1">旅之臨 <a class="header-anchor" href="#旅之臨" aria-label="Permalink to “旅之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>仁政之德，參參日息。成都就邑，人受厥福。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為仁德，坤為都邑。參參，多貌。朿晳《補亡詩》參參其稼，宋本作恭恭，依汲古。《史記》舜陶河濱三年，成都邑。</p><h3 id="旅之觀" tabindex="-1">旅之觀 <a class="header-anchor" href="#旅之觀" aria-label="Permalink to “旅之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>牽頭系尾，屈折幾死。周世無人，不知所歸。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《升》之《大畜》。周，汲古作雕，人作仁，依宋元本。</p><h3 id="旅之噬嗑" tabindex="-1">旅之噬嗑 <a class="header-anchor" href="#旅之噬嗑" aria-label="Permalink to “旅之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>教羊逐兔，使魚捕鼠。任非其人，費日無功。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《噬嗑》。捕鼠，宋元本作相捕，依汲古。</p><h3 id="旅之賁" tabindex="-1">旅之賁 <a class="header-anchor" href="#旅之賁" aria-label="Permalink to “旅之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>生角有尾，張孽制家。排羊逐狐，張氏易公，憂禍復凶。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為生，艮為角、為尾、為家，坎為孽，與震連，故曰張孽。《左傳昭十年》蘊利生孽，註：孽，妖害也。震為羊，艮為狐。震為張、為公，上艮為反震，故曰易公。坎為憂禍、為凶，生疑為牛之訛。</p><h3 id="旅之剝" tabindex="-1">旅之剝 <a class="header-anchor" href="#旅之剝" aria-label="Permalink to “旅之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>去安就危，墜陷井池，破我玉螭。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤為安，孤陽在坤上，故曰去安就危。坤為淵，故曰井池。震為玉、為螭，上卦震覆，故曰破我玉螭。○螭，丁本作蝺，失韻，依宋元、汲古本。</p><h3 id="旅之復" tabindex="-1">旅之復 <a class="header-anchor" href="#旅之復" aria-label="Permalink to “旅之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>茹芝餌黃，塗飲玉英。與神通流，長無憂凶。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為芝、為玄黃，震食，故曰茹、曰餌。黃，黃精也，二者皆延年益壽之草。震為大塗、為玉、為萌芽，故曰玉英。震為神，坤為憂凶。</p><h3 id="旅之無妄" tabindex="-1">旅之無妄 <a class="header-anchor" href="#旅之無妄" aria-label="Permalink to “旅之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>體重難飛，未能越關，不離室垣。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>詳《震》之《鼎》。宋元本無末句，依汲古。</p><h3 id="旅之大畜" tabindex="-1">旅之大畜 <a class="header-anchor" href="#旅之大畜" aria-label="Permalink to “旅之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>巢成樹折，傷我彞器。伯踒叔跌，亡羊乃追。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為巢、為成，震木，兌毀，故曰樹折。震為器，艮虎，故曰彞器。《書》宗彞《釋文》引鄭雲彞，虎也。兌毀，故傷。震為伯，艮為叔，兌折，故曰跌。兌為羊，震往，故曰亡羊、曰追。</p><h3 id="旅之頤" tabindex="-1">旅之頤 <a class="header-anchor" href="#旅之頤" aria-label="Permalink to “旅之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>六人俱行，各貴其囊。黃鶴失珠，無以為明。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《噬嗑》。</p><h3 id="旅之大過" tabindex="-1">旅之大過 <a class="header-anchor" href="#旅之大過" aria-label="Permalink to “旅之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>播梅折枝，與母分離，絕不相知。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《坤》。播，種也。宋元本作蟠，依汲古。梅折枝，汲古作枝遷岐，依宋元本。</p><h3 id="旅之坎" tabindex="-1">旅之坎 <a class="header-anchor" href="#旅之坎" aria-label="Permalink to “旅之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>迎福開戶，喜隨我後。曹伯愷悌，為宋國主。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>中爻震為福，艮為戶，震為開，故曰迎福開戶。震為喜、為後、為伯、為主，艮為宋、為國。元本舊註宋以曹師殺公子游，立桓公，依此註則國字似為立字方適。</p><h3 id="旅之離" tabindex="-1">旅之離 <a class="header-anchor" href="#旅之離" aria-label="Permalink to “旅之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>既痴且狂，兩目又盲。箕踞喑啞，名為無中。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>巽進退不果，故曰痴狂。中互大坎，坎黑，故曰目盲。伏震為箕，兌為喑啞。○箕，宋元本作踑，《集韻》踑，長踞也。茲依汲古。中，汲古作用，喑啞作坐喑，依宋元本。</p><h3 id="旅之咸" tabindex="-1">旅之咸 <a class="header-anchor" href="#旅之咸" aria-label="Permalink to “旅之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>金梁鐵柱，千年牢固。完全不腐，聖人安處。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>乾為金鐵，艮為梁柱，乾為千年，艮堅，故曰牢固。互巽為腐，乾為聖人，艮止，故曰安處。</p><h3 id="旅之恒" tabindex="-1">旅之恒 <a class="header-anchor" href="#旅之恒" aria-label="Permalink to “旅之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>裹糗荷糧，與跖相逢。欲飛不得，為罔所獲。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>巽為糗糧，艮為荷。巽為盜賊，故曰與跖相逢。震為飛，坤為網罟。○罔，宋本作網，依元本。</p><h3 id="旅之遯" tabindex="-1">旅之遯 <a class="header-anchor" href="#旅之遯" aria-label="Permalink to “旅之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>彭生為豕，暴龍作災。盜堯衣裳，聚跖荷兵。青禽照夜，三旦夷亡。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>首句依《比》之《蒙》校，各本多作彭名為矢，或彭生為妖。</p><h3 id="旅之大壯" tabindex="-1">旅之大壯 <a class="header-anchor" href="#旅之大壯" aria-label="Permalink to “旅之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>獨夫老婦，不能生子。鰥寡居處。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為夫，兌為老婦，震為子，兌折，故不能生子。伏巽為寡，故曰獨夫。伏艮為鰥。○獨，汲古訛褐，依宋元本。</p><h3 id="旅之晉" tabindex="-1">旅之晉 <a class="header-anchor" href="#旅之晉" aria-label="Permalink to “旅之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>鷦鷯竊脂，巢於小枝。搖動不安，為風所吹。心寒慄慄，常憂殆危。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>慄慄，依《謙》之《遯》，各本多作飄搖。</p><h3 id="旅之明夷" tabindex="-1">旅之明夷 <a class="header-anchor" href="#旅之明夷" aria-label="Permalink to “旅之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>素車木馬，不任負重。王子出征，憂危為咎。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為白，坤為車，故曰素車。震為木、為馬，坤為重，下互坎，坎險，故不任負重。震為王子、為出征，坎為憂危。○馬，汲古作輿，危作疑，均依宋元本。</p><h3 id="旅之家人" tabindex="-1">旅之家人 <a class="header-anchor" href="#旅之家人" aria-label="Permalink to “旅之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>土陷四維，安平不危。利以居止，保有玉女。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>未詳。</p><h3 id="旅之睽" tabindex="-1">旅之睽 <a class="header-anchor" href="#旅之睽" aria-label="Permalink to “旅之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>負牛上山，力劣行難。烈風雨雪，遮遏我前，中道復還。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《剝》。</p><h3 id="旅之蹇" tabindex="-1">旅之蹇 <a class="header-anchor" href="#旅之蹇" aria-label="Permalink to “旅之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>金城鐵郭，上下同力。政平民親，寇不敢賊。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>艮為金鐵、為城郭，坎為平、為賊寇、為民。</p><h3 id="旅之解" tabindex="-1">旅之解 <a class="header-anchor" href="#旅之解" aria-label="Permalink to “旅之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>清潔淵塞，為人所言。證訊詰情，繫於枳溫。甘裳聽斷，昭然蒙恩。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《蠱》。</p><h3 id="旅之損" tabindex="-1">旅之損 <a class="header-anchor" href="#旅之損" aria-label="Permalink to “旅之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>皋陶聽理，岐伯悅喜。西登華首，東歸無咎。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>艮為山、為火，故曰皋陶。舜時士官，故曰聽理。兌為耳、為聽，坤為理也。震為伯，艮山，故曰岐伯。《本草經》黃帝問岐伯，《漢書人物表》上古之時，有岐伯，中古有扁鵲，蓋與黃帝創製醫葯者。兌為西，艮山，故曰華首。震為東、為歸，華，華山；首，雷首山，在蒲阪。</p><h3 id="旅之益" tabindex="-1">旅之益 <a class="header-anchor" href="#旅之益" aria-label="Permalink to “旅之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>低頭竊視，有所畏避。行作不利，酒酸魚敗，眾莫貪嗜。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《鼎》之《解》。不，宋元本作未，依汲古。眾，宋本作重，依元本、汲古。</p><h3 id="旅之夬" tabindex="-1">旅之夬 <a class="header-anchor" href="#旅之夬" aria-label="Permalink to “旅之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>十雞百雛，常與母俱。抱雞捕虎，誰肯為侶。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>此用旅象。旅互巽為雞，兌數十，故曰十雞。伏震為雛、為百，故曰百雛。巽為母，故曰常與母俱。艮為虎、為抱、為捕，巽為寡，故曰無侶。</p><h3 id="旅之姤" tabindex="-1">旅之姤 <a class="header-anchor" href="#旅之姤" aria-label="Permalink to “旅之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>高阜山陵，陂陁顛崩。為國妖祥，元後以薨。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>《左傳僖十四年》沙麓崩，晉卜偃曰：期年將有大咎，國幾亡，次年，惠公被執；又九年懷公殺於高梁。姤通復。艮為山陵，初至三艮覆，故曰顛崩。坤為國、為妖祥、為喪，故曰薨。震長，故曰元。震為君，故曰元後。○陂，汲古作峻，依宋元本。又《國語》岐山崩，三川竭，幽王亡。</p><h3 id="旅之萃" tabindex="-1">旅之萃 <a class="header-anchor" href="#旅之萃" aria-label="Permalink to “旅之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>六鷁退飛，為襄敗祥。陳師合戰，左股夷傷。遂以崩薨，霸功不成。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>詳《蹇》之《蠱》。</p><h3 id="旅之升" tabindex="-1">旅之升 <a class="header-anchor" href="#旅之升" aria-label="Permalink to “旅之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>異國殊俗，情不相得。金木為仇，百賊擅殺。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>末句依《夬》之《比》校，宋元本作百戰檀谷，汲古作酋賊擅役。</p><h3 id="旅之困" tabindex="-1">旅之困 <a class="header-anchor" href="#旅之困" aria-label="Permalink to “旅之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>鴉噪庭中，以戎災凶。重門擊柝，備憂暴客。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>詳《大過》之《渙》。《左傳襄十三年》有鳥呌於宋太廟，曰嘻嘻出出，後果災。</p><h3 id="旅之井" tabindex="-1">旅之井 <a class="header-anchor" href="#旅之井" aria-label="Permalink to “旅之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>慈母念子，享賜得士。蠻夷來服，以安王室，側陋逢時。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>巽為母，巽順，故曰慈母。坎為念，伏震為子，故曰念子。兌為享，伏震為土、為王，艮為室、為時，坎為側陋。○念，各本皆作赤。第三句皆作獲夷服除，茲依《漸》之《咸》校。士，宋元本作土，依汲古。室，宋本、汲古作家，茲依元本。</p><h3 id="旅之革" tabindex="-1">旅之革 <a class="header-anchor" href="#旅之革" aria-label="Permalink to “旅之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>遷延惡人，使德不通。炎旱為殃，年谷大傷。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>遷延，依《坤》之《大有》校，宋元本作剗跡，汲古作跡造。殃，宋元本作災，不協，依汲古。</p><h3 id="旅之鼎" tabindex="-1">旅之鼎 <a class="header-anchor" href="#旅之鼎" aria-label="Permalink to “旅之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>躬履孔德，以待朿帛。文君燎獵，呂尚獲福。號稱太師，封建齊國。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坤為躬，震為履、為德、為孔。孔，大也。本卦巽為帛，離為文，乾為君。文君，文王也。震為獵，艮火，故曰燎獵，言文王出獵，遇呂尚也。乾為福、為師，巽齊坤國，故曰封建齊國。○第二句汲古作以帶朿帶。</p><h3 id="旅之震" tabindex="-1">旅之震 <a class="header-anchor" href="#旅之震" aria-label="Permalink to “旅之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>徵將止惡，鼓鞞除賊。慶仲奔莒，子般獲福。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為徵、為鼓鞞。坎為邪、為惡、為賊，《月令》仲夏命樂師修鞀鞞鼓。坎為仲，震喜，故曰慶仲。互艮為邑，震往，故曰奔莒。按：《左傳莊三十二年》共仲使圉人犖賊子般於黨氏，共仲即慶父，閔二年奔莒，茲雲獲福，於事正反，疑福為逼之訛字，抑如丁宴說般為谷之訛。谷，共仲孫，文十年魯人立之，所謂谷也，豐下必有後於魯國也。般谷形近，疑要丁說是也。</p><h3 id="旅之艮" tabindex="-1">旅之艮 <a class="header-anchor" href="#旅之艮" aria-label="Permalink to “旅之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>良夫淑女，配合相保。多孫眾子，歡樂長久。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為夫，伏兌為女，震為善，故曰良夫淑女。坎為合，艮為保，艮兌為夫婦，故曰配合相保。艮為孫，震為子，坎眾，故曰多孫眾子。震樂，艮久。○眾，汲古作壽，依宋元本。</p><h3 id="旅之漸" tabindex="-1">旅之漸 <a class="header-anchor" href="#旅之漸" aria-label="Permalink to “旅之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>蜲蛇四牡，思念父母。王事靡盬，不得安處。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>漸上巽，巽為蛇，伏震為馬，卦數四，故曰蜲蛇四牡。坎為思念，震父巽母，震為王，巽隕落，故曰王事靡盬。盬，惡也。《前漢息夫躬傳》器用盬惡。艮為安，坎險，故曰不得安處。按：林詞皆《詩小雅》語。○蜲蛇，汲古作逶迤，依宋元本。牡，宋本訛壯，依元本、汲古。得，元本作我，依宋本。</p><h3 id="旅之歸妹" tabindex="-1">旅之歸妹 <a class="header-anchor" href="#旅之歸妹" aria-label="Permalink to “旅之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>水壞我里，東流為海。龜鳧歡囂，不得安居。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《兌》。龜鳧，汲古作龜鼉，宋元本作鳧龜，依《泰》之《兌》校。</p><h3 id="旅之豐" tabindex="-1">旅之豐 <a class="header-anchor" href="#旅之豐" aria-label="Permalink to “旅之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>朿帛戔戔，賻我孟宣。徵召送君，變號易字。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>巽為帛，伏艮為手，故曰朿帛戔戔。馬雲委積貌，《子夏傳》作殘，茲曰賻我孟宣，是焦義與馬同也。伏震為孟、為宣、為君。事實未詳。○第四句汲古作處號易子，依宋元本。</p><h3 id="旅之旅" tabindex="-1">旅之旅 <a class="header-anchor" href="#旅之旅" aria-label="Permalink to “旅之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>羅網四張，鳥無所翔。征伐窮極，饑渴不食。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>詳《革》之《泰》。</p><h3 id="旅之巽" tabindex="-1">旅之巽 <a class="header-anchor" href="#旅之巽" aria-label="Permalink to “旅之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>乾行天德，覆贍六合。嘔喣成熟，使我福德。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>二五皆陽，故曰乾行天德。覆贍六合者，言乾天覆徧六合也。贍，《說文》給也，《玉篇》周也。伏坎為合，數六，故曰六合。嘔喣，猶吹噓養育也。兌口，故曰嘔喣。伏艮為成、為我，伏震為福德。○覆贍，局本作履贍，象亦合，茲依宋元、汲古本。喣，元本作呴，依宋本、汲古。嘔喣，音歐詡。</p><h3 id="旅之兌" tabindex="-1">旅之兌 <a class="header-anchor" href="#旅之兌" aria-label="Permalink to “旅之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>秦晉大國，更相剋賊。獲惠質圉，鄭被其咎。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>兌西為秦，伏震為晉，艮為國，互巽為賊，兌毀折，三至上正反兌巽，故曰更相剋賊。伏震為德惠，艮為圉守也。《詩大雅》孔棘我圉，《左傳》亦聊以固吾圉。惠，晉惠公，僖十五年為秦所獲，後秦放惠公歸，以子圉質於秦。伏艮，故曰獲、曰質。伏坎為鄭，慶鄭也，慶鄭以惠公違諫，不救惠公，及被釋，殺慶鄭而後入。○首句汲古作秦並六國，非，依宋元本。</p><h3 id="旅之渙" tabindex="-1">旅之渙 <a class="header-anchor" href="#旅之渙" aria-label="Permalink to “旅之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>晦昧昏冥，君無紀綱。甲午成亂，簡公喪亡。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>坎隱伏，故曰晦冥。震為君，巽為繩、為紀綱，艮為時、為甲，納丙，故曰甲午。春秋哀十四年甲午，齊陳恆弒其君王於舒州。壬，簡公名也。陳恆，陳成子也。甲午成亂者，言成子作亂，弒簡公也。震為簡、為公，巽隕，故喪亡。冥，宋元本作明，依汲古。午，元本、汲古作子，依丁本。</p><h3 id="旅之節" tabindex="-1">旅之節 <a class="header-anchor" href="#旅之節" aria-label="Permalink to “旅之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>三足無頭，莫知所之。心狂睛傷，莫使為明，不見日光。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《復》。日，宋元本作月，非，依汲古。睛，汲古作精，依宋元本。兌半離，故曰睛傷。</p><h3 id="旅之中孚" tabindex="-1">旅之中孚 <a class="header-anchor" href="#旅之中孚" aria-label="Permalink to “旅之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>長夜短日，陰為陽賊。萬物空枯，藏於北陸。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《漸》。</p><h3 id="旅之小過" tabindex="-1">旅之小過 <a class="header-anchor" href="#旅之小過" aria-label="Permalink to “旅之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>依宵夜游，與君相遭。除煩解惑，使我無憂。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《歸妹》之《大有》。依《小過》之《否》作衣，《說文》衣，依也，義同。</p><h3 id="旅之既濟" tabindex="-1">旅之既濟 <a class="header-anchor" href="#旅之既濟" aria-label="Permalink to “旅之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>逐鹿南山，利入我門。陰陽和調，國無災殘。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>長子出游，須其仁君。此皆用半象。陰陽和調，謂陰陽爻相等而當位也。</p><h3 id="旅之未濟" tabindex="-1">旅之未濟 <a class="header-anchor" href="#旅之未濟" aria-label="Permalink to “旅之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>請騁左耳，嗇不我與，驅我父母。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>未詳。騁，宋元本作冀，與驅作驅與，均依汲古。左，汲古作作，依宋元本。按：《周禮夏官大司馬》，大獸公之，小獸私之，獲者取左耳以計功，然曰騁則左耳或為綠耳。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
